draw:
var r = p.ratio;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var padL = W * 0.12, padR = W * 0.06, padT = H * 0.16, padB = H * 0.22;
var gw = W - padL - padR, gh = H - padT - padB;
var vMax = 4.2, tMax = 1.35;
var X = function (v) { return padL + (v / vMax) * gw; };
var Y = function (T) { return padT + gh - (T / tMax) * gh; };

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + gh); ctx.lineTo(padL + gw, padT + gh);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("volume", padL + gw / 2, padT + gh + 30);
ctx.save();
ctx.translate(padL - 34, padT + gh / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("temperature", 0, 0);
ctx.restore();

var Ti = 1.0;
var xi = X(1), yi = Y(Ti), xf = X(r), yf = Y(Ti);

// isothermal reversible path
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(xi, yi); ctx.lineTo(xf, yf); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.textAlign = "center";
ctx.fillText("slow isothermal, heat flows in", (xi + xf) / 2, yi - 12);

// detour path: adiabat down then isotherm then constant volume back up
ctx.strokeStyle = C.figure;
ctx.setLineDash([5, 4]);
ctx.beginPath();
ctx.moveTo(xi, yi);
for (var i = 0; i <= 40; i++) {
  var v = 1 + (r - 1) * (i / 40);
  var Tad = Ti * Math.pow(1 / v, 2 / 3);
  ctx.lineTo(X(v), Y(Tad));
}
ctx.lineTo(xf, yf);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("adiabat, then reheat at fixed volume", (xi + xf) / 2, Y(Ti * Math.pow(1 / r, 2 / 3)) + 26);

// irreversible free expansion: jagged, drawn off the surface
ctx.strokeStyle = C.ink;
ctx.setLineDash([2, 3]);
ctx.beginPath();
ctx.moveTo(xi, yi);
for (var k = 1; k <= 12; k++) {
  var u = k / 12;
  var wob = Math.sin(k * 1.9) * gh * 0.11;
  ctx.lineTo(xi + (xf - xi) * u, yi - gh * 0.30 * Math.sin(Math.PI * u) + wob * (1 - u));
}
ctx.lineTo(xf, yf);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("free expansion: no path at all", (xi + xf) / 2, yi - gh * 0.42);

// endpoints
function dot(x, y, lab, side) {
  ctx.fillStyle = C.ink;
  ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
  ctx.textAlign = side;
  ctx.fillText(lab, x + (side === "right" ? -10 : 10), y + 18);
}
dot(xi, yi, "start: V, T", "right");
dot(xf, yf, "end: " + r.toFixed(1) + "V, same T", "left");

var dS = 8.31 * Math.log(r);
ctx.fillStyle = C.accent;
ctx.textAlign = "center";
ctx.fillText("every route between these two dots gives the same entropy change",
  padL + gw / 2, padT - 4);

out.note = "per mole, entropy change = R ln(" + r.toFixed(1) + ") = " + dS.toFixed(2) + " J/K, whichever route you invent";
